export function availableCities(zone,other){const b=directory.find(a=>a.id===other);return directory.filter(a=>{const route=[a,b].some(x=>x?.zone==='international')?'international':[a,b].some(x=>x?.zone==='hmt')?'hmt':'domestic';return a.id!==other&&(zone==='all'||route===zone);});}
export function matchCities(zone,other,text=""){const t=text.trim().toLowerCase();return availableCities(zone,other).filter(a=>!t||[a.id,a.name,a.airport,a.keywords].join(" ").toLowerCase().includes(t)).sort((a,b)=>(b.id===text.toUpperCase())-(a.id===text.toUpperCase())||Number(/[\u4e00-\u9fff]/.test(b.name))-Number(/[\u4e00-\u9fff]/.test(a.name))).slice(0,60);}
